-- core_ui/internal/notifications.lua
-- Notification system for on-screen messages

local notifications_state = {\n    active = {},\n}\n\nlocal function notify(player, text, level)\n    if type(player) == \"string\" then\n        player = minetest.get_player_by_name(player)\n    end\n    if not player or not player:is_player() or type(text) ~= \"string\" then\n        return false\n    end\n    local prefix = \"\"\n    if level == \"warning\" then\n        prefix = \"[WARNING] \"\n    elseif level == \"error\" then\n        prefix = \"[ERROR] \"\n    elseif level == \"info\" then\n        prefix = \"[INFO] \"\n    end\n    minetest.chat_send_player(player:get_player_name(), prefix .. text)\n    return true\nend\n\nlocal function notify_icon(player, text, icon)\n    if type(player) == \"string\" then\n        player = minetest.get_player_by_name(player)\n    end\n    if not player or not player:is_player() or type(text) ~= \"string\" then\n        return false\n    end\n    local message = text\n    if icon and type(icon) == \"string\" then\n        message = icon .. \" \" .. text\n    end\n    minetest.chat_send_player(player:get_player_name(), message)\n    return true\nend\n\nlocal function notify_timed(player, text, duration)\n    if type(player) == \"string\" then\n        player = minetest.get_player_by_name(player)\n    end\n    if not player or not player:is_player() or type(text) ~= \"string\" then\n        return false\n    end\n    if type(duration) ~= \"number\" then\n        duration = 5\n    end\n    notify(player, text)\n    return true\nend\n\nlocal function clear_notifications(player)\n    if type(player) == \"string\" then\n        player = minetest.get_player_by_name(player)\n    end\n    if not player or not player:is_player() then\n        return false\n    end\n    notifications_state.active[player:get_player_name()] = {}\n    return true\nend\n\nlocal function queue_notification(player, text, priority)\n    if type(player) == \"string\" then\n        player = minetest.get_player_by_name(player)\n    end\n    if not player or not player:is_player() or type(text) ~= \"string\" then\n        return false\n    end\n    local name = player:get_player_name()\n    notifications_state.active[name] = notifications_state.active[name] or {}\n    table.insert(notifications_state.active[name], {\n        text = text,\n        priority = priority or 0,\n        created = os.time(),\n    })\n    return true\nend\n\nreturn {\n    notify = notify,\n    notify_icon = notify_icon,\n    notify_timed = notify_timed,\n    clear_notifications = clear_notifications,\n    queue_notification = queue_notification,\n}
